async function downloadWelcomeGraphic(){
  try{await chapterLogo.decode()}catch(error){return}

  // Actual landscape member-card artwork, not a square post containing a second card.
  const c=document.createElement('canvas'); c.width=1600;c.height=1000;
  const g=c.getContext('2d'), w=c.width,h=c.height;
  const base=g.createLinearGradient(0,0,w,h);
  base.addColorStop(0,'#C6142D');base.addColorStop(.47,'#A30022');base.addColorStop(1,'#520012');
  g.fillStyle=base;g.fillRect(0,0,w,h);
  // Subtle machined-metal lines and dimensional highlights
  g.save();g.strokeStyle='rgba(255,255,255,.065)';g.lineWidth=1;
  for(let i=-900;i<2400;i+=18){g.beginPath();g.moveTo(i,0);g.lineTo(i+650,h);g.stroke()}
  g.restore();
  const glow=g.createRadialGradient(1450,80,20,1450,80,850);
  glow.addColorStop(0,'rgba(255,196,208,.29)');glow.addColorStop(1,'rgba(255,255,255,0)');
  g.fillStyle=glow;g.fillRect(0,0,w,h);
  // Tight diagonal pearlescent glint, as on the animated card.
  const glint=g.createLinearGradient(300,0,1050,h);
  glint.addColorStop(0,'rgba(255,255,255,0)');
  glint.addColorStop(.39,'rgba(255,255,255,0)');
  glint.addColorStop(.495,'rgba(255,255,255,.14)');
  glint.addColorStop(.51,'rgba(255,255,255,.25)');
  glint.addColorStop(.53,'rgba(255,255,255,.07)');
  glint.addColorStop(.68,'rgba(255,255,255,0)');
  glint.addColorStop(1,'rgba(255,255,255,0)');
  g.fillStyle=glint;g.fillRect(0,0,w,h);
  // Large precision gear watermark, with vector teeth (rather than a font emoji).
  g.save();g.translate(1340,660);g.rotate(-.12);
  g.fillStyle='rgba(255,255,255,.07)';g.beginPath();
  for(let k=0;k<96;k++){const a=k*Math.PI*2/96,r=(k%8<4?300:272);g.lineTo(Math.cos(a)*r,Math.sin(a)*r)}
  g.closePath();g.moveTo(155,0);g.arc(0,0,155,0,Math.PI*2,true);g.fill('evenodd');
  g.restore();
  // Use the chapter's actual logo, rendered in white against scarlet.
  const logoWidth=780,logoHeight=logoWidth*chapterLogo.naturalHeight/chapterLogo.naturalWidth;
  g.save();g.filter='brightness(0) invert(1)';g.drawImage(chapterLogo,90,90,logoWidth,logoHeight);g.restore();
  // Buckeye mark / border box at top right
  g.strokeStyle='rgba(255,255,255,.55)';g.lineWidth=2;
  g.strokeRect(1190,107,302,112);
  g.fillStyle='#fff';g.font='800 26px Arial, sans-serif';g.fillText('SCARLET & GRAY',1216,151);
  g.font='700 19px Arial, sans-serif';g.fillText('BUCKEYE ENGINEERS',1220,185);
  // Personal name—on one line where possible, with intentional baseline
  const name=(($('first').value.trim()+' '+$('last').value.trim()).trim()||'FUTURE BUCKEYE').toUpperCase();
  g.fillStyle='rgba(255,255,255,.78)';g.font='700 23px Arial, sans-serif';
  g.fillText('WELCOME TO THE COMMUNITY',105,552);
  let fs=116;g.font=`900 ${fs}px Arial, sans-serif`;
  while(g.measureText(name).width>1370 && fs>46){fs-=2;g.font=`900 ${fs}px Arial, sans-serif`}
  g.fillStyle='#fff';g.fillText(name,96,688);
  g.fillStyle='rgba(255,255,255,.68)';g.fillRect(104,741,1390,2);
  // Footer takes the same hierarchy as the preview card.
  g.fillStyle='#fff';g.font='800 27px Arial, sans-serif';g.fillText('COMMUNITY',105,818);
  g.fillText('CLASS',570,818);
  g.fillStyle='rgba(255,255,255,.92)';g.font='700 34px Arial, sans-serif';g.fillText('ASME OSU',105,862);
  const year=$('year').value.trim();
  g.fillText(/^20\d{2}$/.test(year)?year:'FUTURE ENGINEER',570,862);
  g.save();g.translate(1260,831);g.rotate(-.11);g.strokeStyle='rgba(255,255,255,.8)';g.lineWidth=4;g.strokeRect(-8,-47,264,92);
  g.fillStyle='#fff';g.font='bold 23px Arial, sans-serif';g.fillText('BUILT TO',33,-6);g.fillText('MAKE AN IMPACT',10,25);g.restore();
  // fine edge details
  g.strokeStyle='rgba(255,255,255,.38)';g.lineWidth=3;g.strokeRect(20,20,1560,960);
  const safe=name.replace(/[^a-z0-9]+/gi,'-');
  const a=document.createElement('a');a.download='ASME-Ohio-State-Card-'+safe+'.png';
  const png=c.toDataURL('image/png');
  window.dispatchEvent(new CustomEvent('asme:card-export',{detail:{png}}));
  c.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob);a.href=url;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)},'image/png');
}
function round(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);}
