function copyLinkedInText(value){
  const fallback=()=>{const field=document.createElement('textarea');field.value=value;field.style.position='fixed';field.style.left='-9999px';document.body.appendChild(field);field.select();let ok=false;try{ok=document.execCommand('copy')}catch(e){}field.remove();if(!ok)window.prompt('Copy this information:',value)};
  if(navigator.clipboard&&window.isSecureContext)navigator.clipboard.writeText(value).catch(fallback);
  else fallback();
}
function linkedInPrompt(){
  return `Excited to join the American Society of Mechanical Engineers (ASME) student chapter at The Ohio State University! Looking forward to connecting with fellow engineers, learning from industry events, and getting more involved in the Buckeye engineering community.

Organization: American Society of Mechanical Engineers (ASME) — Ohio State Student Chapter
Role: Member

#OhioState #ASME #MechanicalEngineering`;
}
function showPromptMessage(title,text,footer){
  const safe=text.replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]));
  $('shareNote').style.display='block';
  $('shareNote').innerHTML=`<strong>${title}</strong><span class="prompt-preview">${safe}</span>${footer}`;
}
