reopenGroup.href=trigger.href;
function savePending(value){try{if(value)sessionStorage.setItem(pendingKey,String(Date.now()));else sessionStorage.removeItem(pendingKey)}catch(error){/* The in-memory flow also works when storage is unavailable. */}}
function showReturnPanel(){
  returnPanel.classList.add('is-ready');confirmJoin.disabled=false;confirmJoin.textContent="I've joined — get my card";
  reopenGroup.hidden=false;document.getElementById('joinGroupMeProgress').classList.remove('is-current');thirdProgress.classList.add('is-current');
  document.getElementById('asme-groupme-return-title').textContent='Your card is waiting.';
  document.getElementById('asme-groupme-return-message').textContent="Finish joining in GroupMe, then confirm below. We'll start your celebration from the very beginning.";

}
function beginGroupMe(event){
  if(!event.isTrusted||event.defaultPrevented)return;
  captureProfile();pending=true;away=false;savePending(true);showReturnPanel();
  document.getElementById('asme-groupme-return-title').textContent='Your card is waiting.';
  document.getElementById('asme-groupme-return-message').textContent="Finish joining in GroupMe, then return to Step 3 for your welcome celebration and card.";
  // Leave navigation to the anchor so popup blockers do not intercept it.
}
function returnedFromGroupMe(){
  if(!pending||active||document.visibilityState==='hidden')return;
  showReturnPanel();
  if(away){
    document.getElementById('asme-groupme-return-title').textContent='Ready for your card?';
    document.getElementById('asme-groupme-return-message').textContent="If you've finished joining, confirm below to start your welcome from the beginning. Still need to join? Reopen GroupMe.";
    returnPanel.scrollIntoView({block:'nearest',behavior:'auto'});
  }
}
for(const link of document.querySelectorAll('.asme-join-page a[href]')){
  if(link.href!==trigger.href)continue;
  link.target='_blank';link.rel='noopener noreferrer';link.addEventListener('click',beginGroupMe);
}
reopenGroup.addEventListener('click',beginGroupMe);
window.addEventListener('blur',()=>{if(pending)away=true});
window.addEventListener('focus',returnedFromGroupMe);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&pending)away=true;else returnedFromGroupMe()});
confirmJoin.addEventListener('click',event=>{
  if(!event.isTrusted||(!pending&&!welcomed)||active)return;
  pending=false;welcomed=true;savePending(false);
  returnPanel.classList.add('is-complete');thirdProgress.classList.remove('is-current');thirdProgress.classList.add('is-complete');
  document.getElementById('joinGroupMeProgress').classList.add('is-complete');
  confirmJoin.textContent='Replay celebration';reopenGroup.hidden=true;
  document.getElementById('asme-groupme-return-title').textContent='Your ASME OSU card.';
  document.getElementById('asme-groupme-return-message').textContent='Replay the celebration or download your personalized card.';
  play();
  // Closing the experience should return to the permanent GroupMe link.
  returnFocus=trigger;
});

try{const saved=Number(sessionStorage.getItem(pendingKey));if(saved&&Date.now()-saved<30*60*1000){pending=true;away=true;showReturnPanel();returnedFromGroupMe()}else savePending(false)}catch(error){}
